-- Study Chat Admin Console schema and moderation hardening.
begin;
create table if not exists public.admin_allowlist(email text primary key,enabled boolean not null default true,created_at timestamptz not null default now());
alter table public.admin_allowlist enable row level security;
revoke all on table public.admin_allowlist from anon,authenticated;
grant all on table public.admin_allowlist to service_role;
create table if not exists public.admin_audit_logs(id bigint generated by default as identity primary key,admin_user_id uuid,admin_email text not null,action text not null,target_user_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.admin_audit_logs enable row level security;
revoke all on table public.admin_audit_logs from anon,authenticated;
grant all on table public.admin_audit_logs to service_role;
drop policy if exists "No client access to admin allowlist" on public.admin_allowlist;
create policy "No client access to admin allowlist" on public.admin_allowlist for all to anon,authenticated using(false) with check(false);
drop policy if exists "No client access to admin audit logs" on public.admin_audit_logs;
create policy "No client access to admin audit logs" on public.admin_audit_logs for all to anon,authenticated using(false) with check(false);
alter table public.profiles add column if not exists is_banned boolean not null default false,add column if not exists ban_reason text,add column if not exists banned_at timestamptz,add column if not exists banned_by uuid;
create or replace function private.is_user_banned(p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path='' as $function$ select coalesce((select p.is_banned from public.profiles p where p.id=p_user_id),true); $function$;
revoke all on function private.is_user_banned(uuid) from public,anon;
grant execute on function private.is_user_banned(uuid) to authenticated,service_role;
create or replace function private.guard_profile_moderation_fields() returns trigger language plpgsql set search_path='' as $function$
begin
 if auth.uid() is not null and (new.is_banned is distinct from old.is_banned or new.ban_reason is distinct from old.ban_reason or new.banned_at is distinct from old.banned_at or new.banned_by is distinct from old.banned_by) then raise exception 'Only the admin moderation service may change ban fields'; end if;
 return new;
end;
$function$;
drop trigger if exists guard_profile_moderation_fields on public.profiles;
create trigger guard_profile_moderation_fields before update on public.profiles for each row execute function private.guard_profile_moderation_fields();
drop policy if exists "Members can read messages" on public.messages;
create policy "Members can read messages" on public.messages for select to authenticated using(not private.is_user_banned((select auth.uid())) and private.is_conversation_member(conversation_id,(select auth.uid())));
drop policy if exists "Members can send messages as themselves" on public.messages;
create policy "Members can send messages as themselves" on public.messages for insert to authenticated with check(not private.is_user_banned((select auth.uid())) and sender_id=(select auth.uid()) and private.is_conversation_member(conversation_id,(select auth.uid())));
drop policy if exists "Senders can edit their own messages" on public.messages;
create policy "Senders can edit their own messages" on public.messages for update to authenticated using(not private.is_user_banned((select auth.uid())) and sender_id=(select auth.uid()) and private.is_conversation_member(conversation_id,(select auth.uid()))) with check(not private.is_user_banned((select auth.uid())) and sender_id=(select auth.uid()) and private.is_conversation_member(conversation_id,(select auth.uid())));
drop policy if exists "Members can read their conversations" on public.conversations;
create policy "Members can read their conversations" on public.conversations for select to authenticated using(not private.is_user_banned((select auth.uid())) and private.is_conversation_member(id,(select auth.uid())));
drop policy if exists "Users can create conversations" on public.conversations;
create policy "Users can create conversations" on public.conversations for insert to authenticated with check(not private.is_user_banned((select auth.uid())) and created_by=(select auth.uid()));
drop policy if exists "Members can read conversation membership" on public.conversation_members;
create policy "Members can read conversation membership" on public.conversation_members for select to authenticated using(not private.is_user_banned((select auth.uid())) and (user_id=(select auth.uid()) or private.is_conversation_member(conversation_id,(select auth.uid()))));
drop policy if exists "Authenticated users can read profiles" on public.profiles;
create policy "Authenticated users can read profiles" on public.profiles for select to authenticated using(not private.is_user_banned((select auth.uid())) and coalesce(is_banned,false)=false);
drop policy if exists "Users can insert their own profile" on public.profiles;
create policy "Users can insert their own profile" on public.profiles for insert to authenticated with check((select auth.uid())=id and coalesce(is_banned,false)=false);
drop policy if exists "Users can update their own profile" on public.profiles;
create policy "Users can update their own profile" on public.profiles for update to authenticated using(id=(select auth.uid()) and not private.is_user_banned((select auth.uid()))) with check(id=(select auth.uid()) and not private.is_user_banned((select auth.uid())) and coalesce(is_banned,false)=false);
create or replace function public.search_chat_users(search_text text) returns table(user_id uuid,username text,display_name text,is_online boolean,last_seen timestamptz) language sql stable set search_path='' as $function$
 select p.id,p.username,p.display_name,p.is_online,p.last_seen from public.profiles p
 where not private.is_user_banned((select auth.uid())) and coalesce(p.is_banned,false)=false and p.id<>(select auth.uid())
 and nullif(trim(search_text),'') is not null and (p.username ilike '%'||trim(search_text)||'%' or p.display_name ilike '%'||trim(search_text)||'%')
 order by p.is_online desc,p.display_name asc limit 30;
$function$;
create or replace function public.get_or_create_direct_chat(target_user uuid) returns uuid language plpgsql security definer set search_path='' as $function$
declare me uuid:=auth.uid(); c_id uuid;
begin
 if me is null then raise exception 'Login required'; end if;
 if private.is_user_banned(me) then raise exception 'This account is banned'; end if;
 if target_user is null or target_user=me then raise exception 'Choose another user'; end if;
 if not exists(select 1 from public.profiles p where p.id=target_user and not p.is_banned) then raise exception 'User not found or banned'; end if;
 select c.id into c_id from public.conversations c where c.is_direct=true and private.is_conversation_member(c.id,me) and exists(select 1 from public.conversation_members b where b.conversation_id=c.id and b.user_id=target_user) order by c.created_at asc limit 1;
 if c_id is not null then return c_id; end if;
 insert into public.conversations(created_by,is_group,is_direct,title) values(me,false,true,null) returning id into c_id;
 insert into public.conversation_members(conversation_id,user_id) values(c_id,me),(c_id,target_user) on conflict(conversation_id,user_id) do nothing;
 return c_id;
end;
$function$;
create or replace function public.get_recent_direct_chats() returns table(conversation_id uuid,peer_id uuid,peer_username text,peer_display_name text,peer_avatar_url text,peer_is_online boolean,peer_last_seen timestamptz,last_body text,last_created_at timestamptz,last_sender_id uuid,unread_count bigint) language sql stable security definer set search_path='' as $function$
with my_convs as(select cm.conversation_id,cm.last_read_at from public.conversation_members cm where cm.user_id=auth.uid() and not private.is_user_banned((select auth.uid()))),
direct_peers as(select mc.conversation_id,mc.last_read_at,cm.user_id as peer_id from my_convs mc join public.conversations c on c.id=mc.conversation_id and c.is_direct=true join public.conversation_members cm on cm.conversation_id=mc.conversation_id and cm.user_id<>auth.uid()),
latest as(select distinct on(m.conversation_id)m.conversation_id,m.body,m.created_at,m.sender_id,m.deleted_at,m.delete_for_everyone from public.messages m join direct_peers dp on dp.conversation_id=m.conversation_id order by m.conversation_id,m.created_at desc),
unread as(select dp.conversation_id,count(*)::bigint as unread_count from direct_peers dp join public.messages m on m.conversation_id=dp.conversation_id and m.sender_id<>auth.uid() and coalesce(m.deleted_at is null and not m.delete_for_everyone,true) and (dp.last_read_at is null or m.created_at>dp.last_read_at) group by dp.conversation_id)
select dp.conversation_id,dp.peer_id,p.username,p.display_name,p.avatar_url,p.is_online,p.last_seen,case when l.deleted_at is not null or l.delete_for_everyone then '' else coalesce(l.body,'') end,l.created_at,l.sender_id,coalesce(u.unread_count,0)
from direct_peers dp join public.profiles p on p.id=dp.peer_id and not p.is_banned left join latest l on l.conversation_id=dp.conversation_id left join unread u on u.conversation_id=dp.conversation_id
where not private.is_user_banned((select auth.uid())) order by coalesce(l.created_at,'epoch'::timestamptz) desc,p.display_name asc;
$function$;
create or replace function public.mark_direct_messages_delivered(p_conversation_id uuid) returns void language plpgsql security definer set search_path='' as $function$
declare v_user uuid:=auth.uid(); v_now timestamptz:=clock_timestamp();
begin
 if v_user is null then raise exception 'Login required'; end if;
 if private.is_user_banned(v_user) then raise exception 'This account is banned'; end if;
 if not exists(select 1 from public.conversation_members cm join public.conversations c on c.id=cm.conversation_id where cm.conversation_id=p_conversation_id and cm.user_id=v_user and c.is_direct=true) then raise exception 'Not a member of this direct chat'; end if;
 update public.messages m set delivered_at=v_now where m.conversation_id=p_conversation_id and m.sender_id<>v_user and m.delivered_at is null and m.read_at is null and m.deleted_at is null and not m.delete_for_everyone;
end;
$function$;
create or replace function public.mark_direct_chat_read(p_conversation_id uuid) returns void language plpgsql security definer set search_path='' as $function$
declare v_user uuid:=auth.uid(); v_now timestamptz:=clock_timestamp();
begin
 if v_user is null then raise exception 'Login required'; end if;
 if private.is_user_banned(v_user) then raise exception 'This account is banned'; end if;
 if not exists(select 1 from public.conversation_members cm join public.conversations c on c.id=cm.conversation_id where cm.conversation_id=p_conversation_id and cm.user_id=v_user and c.is_direct=true) then raise exception 'Not a member of this direct chat'; end if;
 update public.conversation_members set last_read_at=greatest(coalesce(last_read_at,'-infinity'::timestamptz),v_now) where conversation_id=p_conversation_id and user_id=v_user;
 update public.messages m set delivered_at=coalesce(m.delivered_at,v_now),read_at=coalesce(m.read_at,v_now) where m.conversation_id=p_conversation_id and m.sender_id<>v_user and m.deleted_at is null and not m.delete_for_everyone and (m.delivered_at is null or m.read_at is null);
end;
$function$;
commit;
